import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

class BinarySearchTest {
    @Test
    void returnsFoundResultWhenIntegerElementIsPresent() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        SearchResult result = SearchUtils.binarySearch(arr, 10);

        assertEquals(SearchResult.found(3), result);
    }

    @Test
    void returnsNotFoundResultWithInsertionPointWhenIntegerElementIsAbsent() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        SearchResult result = SearchUtils.binarySearch(arr, 5);

        assertEquals(SearchResult.notFound(3), result);
    }

    @Test
    void supportsComparableTypesOtherThanInteger() {
        String[] arr = { "apple", "banana", "cherry", "date" };

        SearchResult result = SearchUtils.binarySearch(arr, "cherry");

        assertEquals(SearchResult.found(2), result);
    }

    @Test
    void returnsFoundResultWhenElementIsInsideRange() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        SearchResult result = SearchUtils.binarySearch(arr, 10, 2, 4);

        assertEquals(SearchResult.found(3), result);
    }

    @Test
    void returnsNotFoundResultWhenElementIsOutsideRange() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        SearchResult result = SearchUtils.binarySearch(arr, 10, 0, 3);

        assertEquals(SearchResult.notFound(3), result);
    }

    @Test
    void rejectsInvalidRange() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        assertThrows(IllegalArgumentException.class, () -> SearchUtils.binarySearch(arr, 10, 4, 2));
        assertThrows(IndexOutOfBoundsException.class, () -> SearchUtils.binarySearch(arr, 10, -1, 3));
        assertThrows(IndexOutOfBoundsException.class, () -> SearchUtils.binarySearch(arr, 10, 0, 6));
    }

    @Test
    void exposesIndexOnlyConvenienceMethod() {
        Integer[] arr = { 2, 3, 4, 10, 40 };

        int result = SearchUtils.binarySearchIndex(arr, 10);

        assertEquals(3, result);
    }

    @Test
    void resultOrReturnsIndexOrInsertionPoint() {
        assertEquals(3, SearchResult.found(3).or(-1));
        assertEquals(3, SearchResult.notFound(3).or(-1));
    }
}

public record SearchResult(boolean found, int index, int insertionPoint) {
    public SearchResult {
        if (found && index < 0) {
            throw new IllegalArgumentException("found results must have a non-negative index");
        }

        if (!found && index != -1) {
            throw new IllegalArgumentException("not-found results must use -1 as the index");
        }

        if (insertionPoint < 0) {
            throw new IllegalArgumentException("insertionPoint must be non-negative");
        }

        if (found && insertionPoint != index) {
            throw new IllegalArgumentException("found results must use the index as the insertion point");
        }
    }

    public static SearchResult found(int index) {
        return new SearchResult(true, index, index);
    }

    public static SearchResult notFound(int insertionPoint) {
        return new SearchResult(false, -1, insertionPoint);
    }

    public int or(int defaultIndex) {
        return found ? index : insertionPoint;
    }
}

public final class SearchUtils {
    private SearchUtils() {
    }

    public static <T extends Comparable<? super T>> SearchResult binarySearch(T[] arr, T target) {
        return binarySearch(arr, target, 0, arr.length);
    }

    public static <T extends Comparable<? super T>> SearchResult binarySearch(
            T[] arr, T target, int fromIndex, int toIndex) {
        RangeValidator.validate(arr.length, fromIndex, toIndex);

        int low = fromIndex;
        int high = toIndex - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int comparison = arr[mid].compareTo(target);

            if (comparison == 0) {
                return SearchResult.found(mid);
            }

            if (comparison < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return SearchResult.notFound(low);
    }

    public static <T extends Comparable<? super T>> int binarySearchIndex(T[] arr, T target) {
        return binarySearch(arr, target).index();
    }

    public static <T extends Comparable<? super T>> int binarySearchIndex(
            T[] arr, T target, int fromIndex, int toIndex) {
        return binarySearch(arr, target, fromIndex, toIndex).index();
    }

    private static final class RangeValidator {
        private RangeValidator() {
        }

        static void validate(int length, int fromIndex, int toIndex) {
            if (fromIndex > toIndex) {
                throw new IllegalArgumentException("fromIndex must be less than or equal to toIndex");
            }

            if (fromIndex < 0 || toIndex > length) {
                throw new IndexOutOfBoundsException("range must be within array bounds");
            }
        }
    }
}

